import { supabase } from './supabaseClient';
import { DailySchedule, Interviewer } from './types';

// --- Interviewer Functions ---

export const getInterviewers = async (): Promise<Interviewer[]> => {
  const { data, error } = await supabase.from('interviewers').select('*');
  if (error) {
    console.error('Error fetching interviewers:', error);
    throw error;
  }
  return data || [];
};

export const upsertInterviewer = async (interviewer: Interviewer): Promise<Interviewer> => {
  const { data, error } = await supabase
    .from('interviewers')
    .upsert(interviewer)
    .select()
    .single();

  if (error) {
    console.error('Error upserting interviewer:', error);
    throw error;
  }
  return data;
};

export const addInterviewer = async (interviewer: Omit<Interviewer, 'id'>): Promise<Interviewer> => {
  const { data, error } = await supabase
    .from('interviewers')
    .insert(interviewer)
    .select()
    .single();
  
  if (error) {
    console.error('Error adding interviewer:', error);
    throw error;
  }
  return data;
};

export const deleteInterviewer = async (id: string): Promise<void> => {
  const { error } = await supabase
    .from('interviewers')
    .delete()
    .match({ id });

  if (error) {
    console.error('Error deleting interviewer:', error);
    throw error;
  }
};

// --- Schedule Functions ---

export const getSchedules = async (): Promise<DailySchedule[]> => {
  const { data, error } = await supabase.from('schedules').select('*');
  if (error) {
    console.error('Error fetching schedules:', error);
    throw error;
  }
  // Supabaseからのデータは 'interviewer_id' を使用しますが、アプリの型 'DailySchedule' は 'interviewerId' を期待しています。
  // このため、ここでデータのキーをマッピング（変換）します。
  return data.map(schedule => ({
    ...schedule,
    interviewerId: schedule.interviewer_id,
    timeSlots: schedule.time_slots || [], // time_slotsがnullの場合を考慮して空の配列をセット
  })) as DailySchedule[];
};

export const upsertSchedule = async (schedule: DailySchedule): Promise<DailySchedule> => {
    const scheduleForDb = {
        // idはSupabaseが自動で生成・管理するので、ここでは含めません
        date: schedule.date,
        interviewer_id: schedule.interviewerId,
        time_slots: schedule.timeSlots,
    };

    // 'date'と'interviewer_id'の組み合わせが既に存在する場合は更新(update)、存在しない場合は挿入(insert)する'upsert'処理です。
    const { data, error } = await supabase
        .from('schedules')
        .upsert(scheduleForDb, { onConflict: 'date,interviewer_id' })
        .select()
        .single();

    if (error) {
        console.error('Error upserting schedule:', error);
        throw error;
    }

    // データベースからの戻り値をアプリの型に合わせて変換します。
    return {
        ...data,
        interviewerId: data.interviewer_id,
        timeSlots: data.time_slots || [],
    } as DailySchedule;
};