import { create } from 'zustand';
import { v4 as uuidv4 } from 'uuid';
import { DailySchedule, Interviewer, Reservation, TimeSlot, ReservationState } from './types';
// IndexedDBの代わりに、新しいSupabaseの関数をインポートします
import { getInterviewers, getSchedules, upsertInterviewer, upsertSchedule, addInterviewer as dbAddInterviewer, deleteInterviewer as dbDeleteInterviewer } from './database';

const useReservationStore = create<ReservationState>((set, get) => ({
  interviewers: [],
  schedules: [],
  copiedSlots: null,
  isInitialized: false,

  // アプリ初期化時にSupabaseからデータを取得します
  initializeApp: async () => {
    try {
      const [interviewers, schedules] = await Promise.all([
        getInterviewers(),
        getSchedules(),
      ]);
      set({ interviewers, schedules, isInitialized: true });
    } catch (error) {
      console.error("Error initializing app:", error);
    }
  },

  // スケジュールを追加または更新します
  addOrUpdateSchedule: async (schedule) => {
    try {
      // まずSupabaseにデータを保存します
      const updatedSchedule = await upsertSchedule(schedule);
      // 成功したら、ローカルの状態を更新します
      set(state => {
        const index = state.schedules.findIndex(s => s.date === updatedSchedule.date && s.interviewerId === updatedSchedule.interviewerId);
        if (index !== -1) {
          const newSchedules = [...state.schedules];
          newSchedules[index] = updatedSchedule;
          return { schedules: newSchedules };
        } else {
          return { schedules: [...state.schedules, updatedSchedule] };
        }
      });
    } catch (error) {
      console.error("Error saving schedule:", error);
    }
  },

  // 面談担当者の情報を更新します
  updateInterviewer: async (interviewer) => {
    try {
      const updatedInterviewer = await upsertInterviewer(interviewer);
      set(state => {
          const index = state.interviewers.findIndex(i => i.id === updatedInterviewer.id);
          if (index !== -1) {
              const newInterviewers = [...state.interviewers];
              newInterviewers[index] = updatedInterviewer;
              return { interviewers: newInterviewers };
          } else {
              return { interviewers: [...state.interviewers, updatedInterviewer] };
          }
      });
    } catch (error) {
        console.error("Error updating interviewer:", error);
    }
  },

  addInterviewer: async (interviewer) => {
    try {
      const newInterviewer = await dbAddInterviewer(interviewer);
      set(state => ({
        interviewers: [...state.interviewers, newInterviewer]
      }));
    } catch (error) {
      console.error("Error adding interviewer:", error);
    }
  },

  deleteInterviewer: async (id: string) => {
    try {
      await dbDeleteInterviewer(id);
      set(state => ({
        interviewers: state.interviewers.filter(i => i.id !== id)
      }));
    } catch (error) {
      console.error("Error deleting interviewer:", error);
    }
  },

  // 予約処理：ロジックの大部分は変更ありませんが、最終的な保存先がSupabaseになります
  bookTimeSlot: async (interviewerId, date, timeSlotId, reservationData) => {
    const { schedules, addOrUpdateSchedule } = get();
    const schedule = schedules.find(s => s.date === date && s.interviewerId === interviewerId);
    if (!schedule) return false;

    const timeSlot = schedule.timeSlots.find(ts => ts.id === timeSlotId);
    if (!timeSlot) return false;

    const newReservation: Reservation = { ...reservationData, id: uuidv4() };
    const currentReservations = timeSlot.reservations || [];

    if (!timeSlot.capacity || timeSlot.capacity <= 1) {
      if (currentReservations.length > 0) {
        alert('この枠は既に予約で埋まっています。');
        return false;
      }
      timeSlot.reservations = [newReservation];
    } else {
      if (currentReservations.length >= timeSlot.capacity) {
        alert('この枠は定員に達しています。');
        return false;
      }
      timeSlot.reservations = [...currentReservations, newReservation];
    }

    await addOrUpdateSchedule({ ...schedule });
    return true;
  },

  // キャンセル処理：こちらも最終的な保存先がSupabaseになります
  cancelReservation: async (interviewerId, date, timeSlotId, reservationId, password) => {
    const { schedules, addOrUpdateSchedule } = get();
    const schedule = schedules.find(s => s.date === date && s.interviewerId === interviewerId);
    if (!schedule) return false;

    const timeSlot = schedule.timeSlots.find(ts => ts.id === timeSlotId);
    if (!timeSlot || !timeSlot.reservations) return false;

    const reservationToCancel = timeSlot.reservations.find(r => r.id === reservationId);
    if (!reservationToCancel) {
      alert('キャンセル対象の予約が見つかりません。');
      return false;
    }

    if (password === undefined || reservationToCancel.password === password) {
        timeSlot.reservations = timeSlot.reservations.filter(r => r.id !== reservationId);
        await addOrUpdateSchedule({ ...schedule });
        alert(password === undefined ? '予約をキャンセルしました。(管理者)' : '予約をキャンセルしました。');
        return true;
    } else {
        alert('パスワードが違います。');
        return false;
    }
  },

  setCopiedSlots: (slots) => set({ copiedSlots: slots }),

}));

export default useReservationStore;