import { openDB, DBSchema } from 'idb';
import { InterviewData } from './types';

const DB_NAME = 'diary-app-db';
const DB_VERSION = 2;

export const INTERVIEW_STORE_NAME = 'interviews';

// このデータベースは面談記録(interviews)専用です
interface LocalAppDB extends DBSchema {
  [INTERVIEW_STORE_NAME]: {
    key: string;
    value: InterviewData[];
  };
}

export const dbPromise = openDB<LocalAppDB>(DB_NAME, DB_VERSION, {
  upgrade(db, oldVersion) {
    // interviewsストアが存在しない場合のみ作成
    if (!db.objectStoreNames.contains(INTERVIEW_STORE_NAME)) {
        db.createObjectStore(INTERVIEW_STORE_NAME);
    }
  },
});
